/** Writers: the parts file, API.md (agent skill reference) and DEMOS.md (demo catalog table). */
import type { Manifest } from "./components.ts";
import type { ManifestDemo } from "./demos.ts";
import { API } from "./paths.ts";
import type { ManifestDataAttribute, ManifestPart, ManifestStyling } from "./styling.ts";

export function demosMarkdown(demos: ManifestDemo[]): string {
	return `${[
		"<!-- generated by packages/ui/scripts/build-manifest.ts (bun run --cwd packages/ui manifest -- --skill). Do not edit. -->",
		"# Demo catalog",
		"",
		`Every demo has a stable number. Fetch one with \`get_demo\` (MCP) or ${API}/en/e/NNN.txt.`,
		"",
		"| id | title | group/page | components |",
		"|---|---|---|---|",
		...demos.map(
			(d) => `| ${d.id} | ${cell(d.title)} | ${d.group}/${d.page} | ${d.components.join(", ")} |`
		),
	].join("\n")}\n`;
}

const cell = (v: string) => v.replace(/\|/g, "\\|");

/** One component's override surface: stable parts, internal parts, scoped variables, data attributes. */
function stylingLines(s: ManifestStyling): string[] {
	const code = (xs: string[]) => xs.map((x) => `\`${x}\``).join(" ");
	const lines: string[] = [];
	const stable = s.parts.filter((p) => p.stable).map((p) => p.name);
	const internal = s.parts.filter((p) => !p.stable).map((p) => p.name);
	if (stable.length) lines.push(`Parts: ${code(stable)}`, "");
	if (internal.length) lines.push(`Internal (may change in any release): ${code(internal)}`, "");
	if (s.variables.length) lines.push(`Variables: ${code(s.variables)}`, "");
	if (s.data.length)
		lines.push(
			`Data attributes: ${s.data.map((d) => `\`${d.name}\`${d.values.length ? ` (${d.values.map((v) => `\`${v}\``).join(" ")})` : ""}`).join(", ")}`,
			""
		);
	return lines;
}

export interface PartsFile {
	name: string;
	version: string;
	/** Naming rule, repeated in the file so a consumer tool needs nothing else. */
	rule: string;
	components: {
		name: string;
		import: string;
		parts: ManifestPart[];
		variables: string[];
		data: ManifestDataAttribute[];
	}[];
}

const PARTS_RULE =
	"A `ca-*` class owned by a component is a stable part: renaming or removing it is a breaking change. A `ca-x-*` class and every @keyframes name is internal and may change in any release. Variables and data attributes listed here are stable.";

/** The stable override surface of every component that has one, for `parts.json`, `list_parts` and `workarounds`. */
export function buildParts(m: Manifest): PartsFile {
	return {
		name: m.name,
		version: m.version,
		rule: PARTS_RULE,
		components: m.components
			.filter((c) => c.styling.parts.length || c.styling.variables.length || c.styling.data.length)
			.map((c) => ({ name: c.name, import: c.import, ...c.styling })),
	};
}

/** Markdown of the override surface, one section per component. Deterministic. */
export function partsMarkdown(m: Manifest): string {
	const out = [PARTS_RULE, ""];
	for (const c of buildParts(m).components) out.push(`## ${c.name}`, "", ...stylingLines(c));
	return `${out
		.join("\n")
		.replace(/\n{3,}/g, "\n\n")
		.trimEnd()}\n`;
}

/** Markdown reference of every component's props, snippets and classes, then every other export's signature. Deterministic. */
export function skillMarkdown(m: Manifest): string {
	const out = [
		"<!-- generated by packages/ui/scripts/build-manifest.ts (bun run --cwd packages/ui manifest -- --skill). Do not edit. -->",
		"# Component API reference",
		"",
		`Describes ${m.name}@${m.version}. If the project has another version installed, this file may list props that do not exist there (or miss ones that do): the installed package is the source of truth, through \`ca-ui-mcp\` (\`get_component\`, \`get_export\`) or \`node_modules/${m.name}/dist/components.json\`.`,
		"",
		"Generated from the source types: every prop, default and public `ca-*` class. Hand-written usage examples are in [COMPONENTS.md](./COMPONENTS.md).",
		"Import from the path in each heading. Charts, DataTable, CodeSnippet and the `forms` fields are subpath imports.",
		"",
	];
	for (const c of m.components) {
		out.push(
			`## ${c.name}`,
			"",
			`\`import { ${c.name} } from "${c.import}"\`${c.generics ? ` (generic: \`${c.generics}\`)` : ""}`,
			""
		);
		if (c.deprecated) out.push(`**Deprecated. ${c.deprecated}**`, "");
		if (c.description) out.push(c.description, "");
		if (c.props.length) {
			out.push("| Prop | Type | Default | Notes |", "|---|---|---|---|");
			for (const p of c.props)
				out.push(
					`| \`${p.name}${p.optional ? "?" : ""}\` | \`${cell(p.type)}\` | ${p.default ? `\`${cell(p.default)}\`` : ""} | ${[p.bindable ? "`bind:`" : "", p.description ? cell(p.description) : ""].filter(Boolean).join(" ")} |`
				);
			out.push("");
		}
		if (c.snippets.length)
			out.push(
				`Snippets: ${c.snippets.map((x) => `\`${x.name}\`${x.type.includes("<") ? ` (\`${cell(x.type)}\`)` : ""}${x.description ? `: ${cell(x.description)}` : ""}`).join("; ")}`,
				""
			);
		if (c.extends) out.push(`Also accepts: \`${cell(c.extends)}\``, "");
		out.push(...stylingLines(c.styling));
		if (c.tokens.length) out.push(`Tokens: ${c.tokens.map((x) => `\`${x}\``).join(" ")}`, "");
	}
	out.push(
		"# Non-component exports",
		"",
		"Functions, stores, constants and types every entry point exports besides components. Import from the path in each heading; types use `import type`."
	);
	for (const entry of [...new Set(m.exports.map((e) => e.import))]) {
		const here = m.exports.filter((x) => x.import === entry);
		out.push("", `## ${entry}`, "");
		for (const e of here.filter((x) => x.kind !== "type")) {
			out.push(`### ${e.name}`, "", `\`import { ${e.name} } from "${entry}"\``, "");
			if (e.description) out.push(e.description, "");
			out.push("```ts", e.signature, "```", "");
		}
		const types = here.filter((x) => x.kind === "type");
		if (types.length) {
			out.push("Types:", "", "| Type | Declaration | Notes |", "|---|---|---|");
			for (const t of types)
				out.push(
					`| \`${t.name}\` | \`${cell(t.signature)}\` | ${t.description ? cell(t.description) : ""} |`
				);
			out.push("");
			for (const t of types.filter((x) => x.members)) {
				out.push(`#### ${t.name}`, "", "| Field | Type | Notes |", "|---|---|---|");
				for (const f of t.members ?? [])
					out.push(
						`| \`${f.name}${f.optional ? "?" : ""}\` | \`${cell(f.type)}\` | ${f.description ? cell(f.description) : ""} |`
					);
				out.push("");
			}
		}
	}
	return `${out
		.join("\n")
		.replace(/\n{3,}/g, "\n\n")
		.trimEnd()}\n`;
}
